from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

from .monitor import ensure_daemon
from .service import RunRelayService


def serve(service: RunRelayService, host: str, port: int) -> None:
    # Server snapshots are continuously refreshed while the dashboard is available.
    ensure_daemon(service.root, interval=2.0)
    service.servers.notifier.start()

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):  # noqa: N802
            path = urlparse(self.path).path
            try:
                if path == "/api/experiments":
                    self._json([item.to_dict() for item in service.list()])
                elif path == "/api/servers":
                    self._json([item.to_dict() for item in service.storage.list_servers()])
                elif path == "/api/connectors/feishu":
                    self._json(service.servers.notifier.public_config())
                elif path == "/api/connectors/webhook":
                    self._json(service.servers.notifier.public_webhook_config())
                elif path.startswith("/api/servers/") and path.endswith("/snapshot"):
                    self._json(_required(service.storage.get_snapshot(path.split("/")[3])).to_dict())
                elif path == "/api/monitors":
                    self._json([item.to_dict() for item in service.storage.list_monitors()])
                elif path.startswith("/api/monitors/") and path.endswith("/log"):
                    monitor = _required(service.storage.get_monitor(path.split("/")[3]))
                    log = ""
                    if monitor.log_path:
                        try:
                            log = Path(monitor.log_path).read_text(encoding="utf-8", errors="replace")
                        except FileNotFoundError:
                            pass
                    self._send(200, log, "text/plain; charset=utf-8")
                elif path.startswith("/api/monitors/"):
                    self._json(_required(service.storage.get_monitor(path.split("/")[3])).to_dict())
                elif path == "/servers":
                    self._send(200, _server_page(), "text/html; charset=utf-8")
                else:
                    self._send(200, _monitor_page_v2(), "text/html; charset=utf-8")
            except KeyError as exc:
                self._json({"error": str(exc)}, 404)
            except Exception as exc:
                self._json({"error": str(exc)}, 500)

        def do_POST(self):  # noqa: N802
            path = urlparse(self.path).path
            try:
                payload = self._body()
                if path == "/api/connectors/feishu":
                    service.servers.notifier.save_config(payload)
                    return self._json(service.servers.notifier.public_config(), 200)
                if path == "/api/connectors/feishu/test":
                    return self._json(service.servers.notifier.send_test())
                if path == "/api/connectors/webhook":
                    service.servers.notifier.save_webhook_config(payload)
                    return self._json(service.servers.notifier.public_webhook_config(), 200)
                if path == "/api/connectors/webhook/test":
                    return self._json(service.servers.notifier.send_webhook_test())
                if path == "/api/servers/import-ssh":
                    profiles = service.servers.import_ssh_config(str(payload.get("path", "")))
                    return self._json([item.to_dict() for item in profiles], 201)
                if path == "/api/servers":
                    profile = service.servers.save_server(
                        server_id=payload.get("id"), name=str(payload.get("name", "")),
                        host=str(payload.get("host", "")), port=int(payload.get("port", 22)),
                        username=payload.get("username"), identity_file=payload.get("identity_file"),
                        remote_forwards=payload.get("remote_forwards") or [],
                    )
                    return self._json(profile.to_dict(), 201)
                if path.startswith("/api/servers/") and path.endswith("/watch"):
                    interval = float(payload.get("interval_seconds", 2.0))
                    return self._json(service.servers.start_watch(path.split("/")[3], interval).to_dict())
                if path.startswith("/api/servers/") and path.endswith("/watch/stop"):
                    return self._json(service.servers.stop_watch(path.split("/")[3]).to_dict())
                if path.startswith("/api/servers/") and path.endswith("/test"):
                    return self._json(service.servers.test_connection(path.split("/")[3]).to_dict())
                if path.startswith("/api/servers/") and path.endswith("/refresh"):
                    return self._json(service.servers.refresh_server(path.split("/")[3]).to_dict())
                if path == "/api/monitors":
                    monitor = service.servers.start_monitor(
                        server_id=str(payload.get("server_id", "")),
                        pid=int(payload["pid"]) if payload.get("pid") not in (None, "") else None,
                        command_filter=payload.get("command_filter") or None,
                        user_filter=payload.get("user_filter") or None,
                        stdout_path=payload.get("stdout_path") or None,
                        stderr_path=payload.get("stderr_path") or None,
                        interval_seconds=float(payload.get("interval_seconds", 5)),
                    )
                    return self._json(monitor.to_dict(), 201)
                if path.startswith("/api/monitors/") and path.endswith("/stop"):
                    return self._json(service.servers.stop_monitor(path.split("/")[3]).to_dict())
                return self._json({"error": "Unknown API route"}, 404)
            except KeyError as exc:
                self._json({"error": str(exc)}, 404)
            except (TypeError, ValueError) as exc:
                self._json({"error": str(exc)}, 400)
            except Exception as exc:
                self._json({"error": str(exc)}, 502)

        def do_DELETE(self):  # noqa: N802
            path = urlparse(self.path).path
            try:
                if path.startswith("/api/servers/"):
                    profile = service.servers.delete_server(path.split("/")[3])
                    return self._json({"deleted": profile.id, "name": profile.name})
                return self._json({"error": "Unknown API route"}, 404)
            except KeyError as exc:
                self._json({"error": str(exc)}, 404)
            except ValueError as exc:
                self._json({"error": str(exc)}, 409)
            except Exception as exc:
                self._json({"error": str(exc)}, 500)

        def _body(self) -> dict:
            length = int(self.headers.get("Content-Length", "0"))
            value = json.loads((self.rfile.read(length) if length else b"{}").decode("utf-8"))
            if not isinstance(value, dict):
                raise ValueError("JSON body must be an object")
            return value

        def _json(self, value, status: int = 200):
            self._send(status, json.dumps(value, ensure_ascii=False), "application/json; charset=utf-8")

        def _send(self, status: int, body, content_type: str):
            if isinstance(body, str):
                body = body.encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *_args):
            return

    server = ThreadingHTTPServer((host, port), Handler)
    print(f"Dreamkeeper dashboard: http://{host}:{server.server_port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        service.servers.notifier.stop()
        server.server_close()


def _required(value):
    if value is None:
        raise KeyError("Not found")
    return value


