_LAYOUT_PATCH = r'''<script>
function fixMonitorLayout(){const detail=$('server-detail');if(!detail)return;const tables=detail.querySelectorAll('table');const table=tables[tables.length-1];if(!table)return;table.classList.add('process-table');table.querySelectorAll('tr').forEach(row=>{if(row.querySelector('th'))return;const cell=row.children[5];if(!cell||cell.querySelector('.process-command'))return;const full=cell.textContent.trim();cell.textContent='';const span=document.createElement('span');span.className='process-command';span.dataset.full=full;span.textContent=full.length>88?full.slice(0,88)+'…':full;span.title=full;span.onclick=()=>{span.classList.toggle('expanded');span.textContent=span.classList.contains('expanded')?span.dataset.full:(span.dataset.full.length>88?span.dataset.full.slice(0,88)+'…':span.dataset.full)};cell.appendChild(span)})}if(typeof selected!=='undefined'){const detail=$('server-detail');new MutationObserver(()=>requestAnimationFrame(fixMonitorLayout)).observe(detail,{childList:true,subtree:true});setTimeout(fixMonitorLayout,0);setInterval(fixMonitorLayout,2000)}
</script>'''


_LIVE_STYLE = r'''<style>.gpu-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;margin:14px 0}.gpu-card{border:1px solid var(--line);border-radius:10px;padding:11px;background:rgba(248,250,247,.8)}.gpu-card h3{font-size:13px;margin:0 0 7px;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.gpu-card small{color:var(--muted)}.gpu-metric{margin-top:8px}.gpu-metric-line{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;gap:8px}.bar{height:7px;border-radius:99px;background:#e2e8e3;overflow:hidden;margin-top:4px}.bar span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#5bbd9e,#7f9de8)}.gpu-temp{color:#9a6e2d}</style>'''


_SERVER_PATCH = r'''<script>
async function deleteServer(id){let s=servers.find(x=>x.id===id);if(!confirm((lang==='zh'?'确定删除服务器配置“':'Delete server configuration “')+(s?s.name:id)+(lang==='zh'?'”？':'”?')))return;try{await api('/api/servers/'+id,{method:'DELETE'});show('server-msg',lang==='zh'?'服务器配置已删除。':'Server configuration deleted.','ok');await load()}catch(e){show('server-msg',e.message,'bad')}}function hideForwardColumn(){let h=document.querySelector('th[data-i18n="forwards"]');if(h)h.remove();document.querySelectorAll('#server-rows tr').forEach(row=>{if(row.children.length>5&&row.children[4])row.children[4].remove()})}function hideActionHeading(){let h=document.querySelector('th[aria-label="actions"]');if(h){h.removeAttribute('aria-label');h.textContent=''}}function installDeleteButtons(){hideForwardColumn();hideActionHeading();document.querySelectorAll('[data-test]').forEach(test=>{if(test.parentElement.querySelector('[data-delete]'))return;let b=document.createElement('button');b.dataset.delete=test.dataset.test;b.dataset.i18n='delete';b.textContent=t('delete');b.onclick=()=>deleteServer(test.dataset.test);test.parentElement.appendChild(b)})}new MutationObserver(installDeleteButtons).observe(document.body,{childList:true,subtree:true});installDeleteButtons();
</script>'''


_MONITOR_PATCH = r'''<script>
if(typeof renderDetail==='function'&&typeof selected!=='undefined'){async function refreshGpuProcessView(){if(!selected)return;let snap=await api('/api/servers/'+encodeURIComponent(selected)+'/snapshot').catch(()=>null);if(!snap)return;let detail=$('server-detail'),tables=detail.querySelectorAll('table');if(!tables.length)return;let gpuProcesses=snap.gpu_processes||((snap.processes||[]).filter(x=>x.gpu_index));let processTable=tables[tables.length-1];processTable.innerHTML='<tr><th>GPU</th><th>PID</th><th>User</th><th>GPU MiB</th><th>State</th><th>Command</th></tr>'+(gpuProcesses.length?gpuProcesses.map(x=>`<tr><td>${esc(x.gpu_index??'—')}</td><td>${esc(x.pid)}</td><td>${esc(x.user||'—')}</td><td>${esc(x.gpu_memory_mib??'—')}</td><td>${esc(x.state||'—')}</td><td>${esc(x.command)}</td></tr>`).join(''):`<tr><td colspan="6">${esc(t('noSnapshot'))}</td></tr>`);let grid=document.getElementById('live-gpus');if(!grid){grid=document.createElement('div');grid.id='live-gpus';grid.className='gpu-grid';tables[0].parentElement.insertBefore(grid,tables[0])}const pct=v=>Math.max(0,Math.min(100,Number(v)||0));grid.innerHTML=(snap.gpus||[]).map(g=>{let mem=pct(Number(g.memory_used_mib)*100/Math.max(1,Number(g.memory_total_mib)));return `<article class="gpu-card"><h3>GPU ${esc(g.index)} · ${esc(g.name)}</h3><div class="gpu-metric"><div class="gpu-metric-line"><span>Memory</span><span>${esc(g.memory_used_mib??'—')} / ${esc(g.memory_total_mib??'—')} MiB</span></div><div class="bar"><span style="width:${mem}%"></span></div></div><div class="gpu-metric"><div class="gpu-metric-line"><span>Utilization</span><span>${esc(g.utilization_percent??'—')}%</span></div><div class="bar"><span style="width:${pct(g.utilization_percent)}%"></span></div></div><div class="gpu-metric-line"><span>Temp</span><span class="gpu-temp">${esc(g.temperature_c??'—')}°C · ${esc(g.power_draw_w??'—')} W</span></div></article>`}).join('');let refresh=$('refresh-server');if(refresh&&!$('watch-server')){let b=document.createElement('button');b.id='watch-server';b.className='secondary';refresh.parentNode.insertBefore(b,refresh);b.onclick=async()=>{try{let running=servers.find(x=>x.id===selected)?.watch_status==='RUNNING';await api('/api/servers/'+selected+(running?'/watch/stop':'/watch'),{method:'POST',headers:{'Content-Type':'application/json'},body:running?'{}':JSON.stringify({interval_seconds:2})});await load()}catch(e){show('monitor-msg',e.message,'bad')}}}let watch=$('watch-server');if(watch){let running=servers.find(x=>x.id===selected)?.watch_status==='RUNNING';watch.textContent=lang==='zh'?(running?'停止实时采样':'启动实时采样'):(running?'Stop live sampling':'Start live sampling')}}const _oldRenderDetail=renderDetail;renderDetail=async()=>{await _oldRenderDetail();await refreshGpuProcessView()};refreshGpuProcessView()}
</script>'''


